function p11_edit_skill(int $id, array $extra=[], bool $approve=true): void {
 global $management,$admin;
 wp_set_current_user($admin); $old=$management->skill($id); $tr=[];
 foreach($old['translations'] as $locale=>$translation) { $tr[$locale]=array_intersect_key($translation,array_flip(['title','slug','summary','content','seo_title','seo_description'])); }
 $payload=['save_mode'=>'pending','revision'=>(int)$old['skill']['revision'],'repository_id'=>$old['skill']['repository_id'],'source_path'=>$old['skill']['source_path'],'translations'=>$tr,'category_ids'=>array_map('intval',$old['categories']??[]),'tag_ids'=>array_map('intval',$old['tags']??[])];
 $management->saveSkill($id,array_replace($payload,$extra));
 if($approve) $management->review($id,'approved','unknown','Synthetic QA reapproval',p11_skill_revision($id));
}
function p11_topic_payload(string $kind,string $slug,array $skills,bool $zh=true): array {
 $name=$kind==='collection'?'title':'name';
 $t=['en_US'=>[$name=>'QA '.$slug,'slug'=>$slug,'description'=>'Synthetic editorial content for isolated QA.','seo_title'=>'QA SEO '.$slug,'seo_description'=>'QA description.']];
 if($zh) $t['zh_CN']=[$name=>'测试专题 '.$slug,'slug'=>$slug,'description'=>'独立测试使用的中文专题内容。'];
 return ['status'=>'published','sort_order'=>0,'translations'=>$t,'skills'=>$skills];
}
